SELECT sm.sm_ship_mode_id, sm.sm_type, sm.sm_carrier, d.d_year, d.d_month_seq, SUM(cr.cr_return_amount) AS total_return_amount, SUM(cr.cr_net_loss) AS total_net_loss, MIN(cr.cr_return_tax) AS min_return_tax, CASE WHEN SUM(cr.cr_net_loss) < 0 THEN 'Profit' ELSE 'Loss' END AS profit_indicator FROM catalog_returns cr JOIN ship_mode sm ON cr.cr_ship_mode_sk = sm.sm_ship_mode_sk JOIN date_dim d ON cr.cr_returned_date_sk = d.d_date_sk GROUP BY sm.sm_ship_mode_id, sm.sm_type, sm.sm_carrier, d.d_year, d.d_month_seq ORDER BY d.d_year, d.d_month_seq, total_net_loss DESC
